def pss_nodes(value=PSS_MAX_SIGNATURE):
    return {'/configurations/conf/signature': {'algo': b'sha256,rsa2048\0',
        'padding': b'pss\0', 'key-name-hint': b'dev\0', 'value': value}}


def fdt(root):
    strings, table = bytearray(), {}
    structure = bytearray()

    def emit(name, value):
        structure.extend(struct.pack('>I', 1) + name.encode() + b'\0')
        structure.extend(bytes(-len(structure) % 4))
        for key, content in value.items():
            if isinstance(content, dict):
                emit(key, content)
            else:
                if key not in table:
                    table[key] = len(strings)
                    strings.extend(key.encode() + b'\0')
                structure.extend(struct.pack('>III', 3, len(content), table[key]) + content)
                structure.extend(bytes(-len(structure) % 4))
        structure.extend(struct.pack('>I', 2))

    emit('', root)
    structure.extend(struct.pack('>I', 9))
    offset = 56
    strings_offset = offset + len(structure)
    total = strings_offset + len(strings)
    header = struct.pack('>10I', 0xd00dfeed, total, offset, strings_offset, 40, 17, 16,
                         0, len(strings), len(structure))
    return header + bytes(16) + structure + strings


class BootloaderTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name)

    def test_clean_control_tree_and_key_injection_detection(self):
        path = self.root / 'control.dtb'
        path.write_bytes(fdt({'model': b'board\0'}))
        bootloader._clean_dtb(path)
        path.write_bytes(fdt({'signature': {'key-dev': {'required': b'conf\0'}}}))
        with self.assertRaises(BuildError):
            bootloader._clean_dtb(path)

    def test_vendor_signer_settings_are_private_and_rk3588_only(self):
        source = self.root / 'source-signer'
        source.write_bytes(b'trusted executable fixture')
        source.chmod(0o755)
        work = self.root / 'work'
        work.mkdir()
        result = bootloader._private_signer({'rk_sign_tool':source,'boot_merger':source}, work)
        executable = result['rk_sign_tool']
        self.assertEqual(executable.read_bytes(), source.read_bytes())
        self.assertEqual((executable.parent/'boot_merger').read_bytes(), source.read_bytes())
        self.assertNotEqual(executable, source)
        self.assertEqual(executable.parent.stat().st_mode & 0o777, 0o700)
        setting = executable.parent / 'setting.ini'
        self.assertEqual(setting.stat().st_mode & 0o777, 0o600)
        parser = bootloader.configparser.ConfigParser(interpolation=None)
        parser.read(setting)
        selected = {key:value for key,value in parser.items('System') if value}
        self.assertEqual(selected, {name:'3588' for name in ('support_chip','hard_sign_pss','new_crypto','new_idb')})
        self.assertFalse((source.parent / 'setting.ini').exists())

    def test_fdt_rejects_truncated_property(self):
        path = self.root / 'bad.dtb'
        path.write_bytes(fdt({'model': b'board\0'})[:-2])
        with self.assertRaises(BuildError):
            bootloader.read_fdt(path)

    def test_elf_extracts_file_bytes_instead_of_zero_filled_memory_size(self):
        path = self.root / 'bl31.elf'
        ident = b'\x7fELF\x02\x01\x01' + bytes(9)
        header = struct.pack('<16sHHIQQQIHHHHHH', ident, 2, 183, 1, 0, 64, 0, 0,
                             64, 56, 1, 0, 0, 0)
        program = struct.pack('<IIQQQQQQ', 1, 5, 120, 0x60000, 0x60000, 4, 100, 4)
        path.write_bytes(header + program + b'ATF!')
        self.assertEqual(bootloader.elf_load_segments(path), {0x60000:b'ATF!'})
        path.write_bytes(header + program + b'AT')
        with self.assertRaises(BuildError):
            bootloader.elf_load_segments(path)

    def test_compressed_firmware_has_binary_plaintext_digest(self):
        path = self.root / 'tee.bin'
        path.write_bytes(b'example firmware' * 200)
        first = bootloader._compressed(path, 0).read_bytes()
        second = bootloader._compressed(path, 0).read_bytes()
        self.assertEqual(first, second)
        self.assertEqual(gzip.decompress(first), path.read_bytes())
        self.assertEqual((self.root / 'tee.bin.digest').read_bytes(), hashlib.sha256(path.read_bytes()).digest())
        self.assertEqual(len((self.root / 'tee.bin.digest').read_bytes()), 32)

    def test_fit_payload_is_checked_against_source_and_hash_node(self):
        source = self.root / 'Image'
        source.write_bytes(b'kernel payload')
        tree = {'images': {'kernel': {'data': source.read_bytes(), 'hash': {
            'algo': b'sha256\0', 'value': hashlib.sha256(source.read_bytes()).digest()}}}}
        path = self.root / 'boot.img'
        path.write_bytes(fdt(tree))
        _, result = bootloader._fit_hashes(path, {'kernel':source})
        self.assertEqual(result['kernel']['sha256'], hashlib.sha256(source.read_bytes()).hexdigest())
        source.write_bytes(b'changed kernel')
        with self.assertRaises(BuildError):
            bootloader._fit_hashes(path, {'kernel':source})

    def test_signature_must_cover_resource_hash(self):
        nodes = {'/configurations/conf/signature': {'hashed-nodes':
            b'/configurations/conf\0/images/resource\0'}}
        with self.assertRaises(BuildError):
            bootloader._assert_signature_coverage(nodes, {'resource':None})
        nodes['/configurations/conf/signature']['hashed-nodes'] += b'/images/resource/hash\0'
        bootloader._assert_signature_coverage(nodes, {'resource':None})

    def test_maximum_pss_signature_is_checked_with_the_injected_public_key(self):
        control = self.root / 'control.dtb'
        control.write_bytes(fdt({'signature': {'key-dev': {
            'rsa,num-bits': struct.pack('>I', 2048),
            'rsa,exponent': struct.pack('>Q', 65537),
            'rsa,modulus': PSS_MODULUS, 'required': b'conf\0'}}}))
        report = bootloader._assert_pss_signature(pss_nodes(), bootloader._key_identity(control))
        self.assertEqual(report, {'algorithm': 'sha256,rsa2048', 'padding': 'pss',
            'pss_salt_length': 'maximum', 'pss_salt_bytes': 222})

    def test_valid_digest_length_pss_signature_is_rejected(self):
        # A checker using RSA_PSS_SALTLEN_AUTO accepts this valid 32-byte salt.
        # Secure-boot output must reject it independently of that host checker.
        with self.assertRaisesRegex(BuildError, r'maximum \(222 bytes\), got 32'):
            bootloader._assert_pss_signature(pss_nodes(PSS_32_SIGNATURE), (2048, 65537, PSS_MODULUS))

    def test_pss_cannot_be_replaced_by_another_padding_algorithm_or_key(self):
        for property_name, value in (('algo', b'sha256,rsa4096\0'),
                                     ('padding', b'pkcs-1.5\0'),
                                     ('key-name-hint', b'other\0')):
            with self.subTest(property_name=property_name):
                nodes = pss_nodes()
                nodes['/configurations/conf/signature'][property_name] = value
                with self.assertRaises(BuildError):
                    bootloader._assert_pss_signature(nodes, (2048, 65537, PSS_MODULUS))

    def test_pss_rejects_truncation_corruption_and_out_of_range_signature(self):
        corrupt = bytearray(PSS_MAX_SIGNATURE)
        corrupt[-1] ^= 1
        for value in (PSS_MAX_SIGNATURE[:-1], bytes(corrupt), PSS_MODULUS):
            with self.subTest(signature=value.hex()[:16]):
                with self.assertRaises(BuildError):
                    bootloader._assert_pss_signature(pss_nodes(value), (2048, 65537, PSS_MODULUS))

    def test_pss_rejects_malformed_trailer_high_bit_and_database_delimiter(self):
        encoded = pow(int.from_bytes(PSS_MAX_SIGNATURE, 'big'), 65537,
                      int.from_bytes(PSS_MODULUS, 'big')).to_bytes(256, 'big')
        cases = []
        bad_trailer = bytearray(encoded)
        bad_trailer[-1] = 0xbd
        cases.append(('trailer', bad_trailer))
        bad_topbit = bytearray(encoded)
        bad_topbit[0] |= 0x80
        cases.append(('high bits', bad_topbit))
        bad_delimiter = bytearray(encoded)
        bad_delimiter[0] ^= 3  # Unmasked first DB byte changes from 0x01 to 0x02.
        cases.append(('delimiter', bad_delimiter))
        cases.append(('size', encoded[:-1]))
        for message, value in cases:
            with self.subTest(case=message):
                with self.assertRaisesRegex(BuildError, message):
                    bootloader._assert_maximum_pss_encoding(value, 2048)

    def test_signed_export_cannot_downgrade_the_pss_salt_policy(self):
        metadata = {'schema_version': 1, 'machine': 'mixtile-core3588e-v2',
            'stage': 'compiled-before-key-injection',
            'capabilities': {'fit_signature': True, 'spl_fit_signature': True},
            'signature': {'algorithm': 'sha256,rsa2048', 'padding': 'pss', 'pss_salt_length': 32}}
        with self.assertRaisesRegex(BuildError, 'maximum salt'):
            bootloader.build_bootloader(self.root, self.root / 'work', self.root / 'output',
                metadata, {}, {}, {}, 0)
        self.assertFalse((self.root / 'work').exists())

    def test_unsigned_template_retains_configuration_without_signature(self):
        source = '/ { configurations { conf { fdt = "fdt"; signature { algo = "sha256,rsa2048"; }; }; }; };'
        result = bootloader._unsigned_its(source)
        self.assertNotIn('signature', result)
        self.assertIn('fdt = "fdt";', result)

    def test_otp_cannot_be_enabled_on_an_unsigned_export(self):
        metadata = {'schema_version':1, 'machine':'mixtile-core3588e-v2',
                    'stage':'compiled-before-key-injection', 'capabilities':{}}
        with self.assertRaises(BuildError):
            bootloader.build_bootloader(self.root, self.root / 'work', self.root / 'output',
                metadata, {}, None, {}, 0, burn_key_hash=True)
        self.assertFalse((self.root / 'work').exists())

    def test_oversized_bootloader_is_rejected_before_writing_slot(self):
        source, target = self.root / 'payload', self.root / 'slot'
        source.write_bytes(b'12345')
        with self.assertRaises(BuildError):
            bootloader._pad(source, target, 4)
        self.assertFalse(target.exists())

    def test_loader_template_cannot_read_an_unselected_host_file(self):
        text = ('[CHIP_NAME]\nNAME=RK3588\n[CODE471_OPTION]\nNUM=1\nPath1=bin/ddr.bin\n'
                '[CODE472_OPTION]\nNUM=1\nPath1=bin/usb.bin\n[LOADER_OPTION]\nNUM=2\n'
                'LOADER1=FlashData\nLOADER2=FlashBoot\nFlashData=bin/ddr.bin\nFlashBoot=@SPL_BINARY@\n'
                '[OUTPUT]\nPATH=loader.bin\n')
        artifacts = [{'role':'ddr', 'path':'rkbin/bin/ddr.bin'}, {'role':'usbplug', 'path':'rkbin/bin/usb.bin'}]
        self.assertEqual(bootloader._loader_configuration(text, artifacts), 'loader.bin')
        with self.assertRaises(BuildError):
            bootloader._loader_configuration(text.replace('FlashData=bin/ddr.bin', 'FlashData=/tmp/unselected-file'), artifacts)


if __name__ == '__main__':
    unittest.main()
